import { addListeners, removeListeners, toPx } from '@splendidlabz/utils/dom'

export function resizer(node, options) {
  const elementToResize = options.target
    ? node.closest(options.target)
    : node.parentElement

  const box = elementToResize.getBoundingClientRect()

  const state = {
    pointerId: null,
    resizing: false,
    prevX: 0,
    prevY: 0,
    widths: {
      min: toPx(options.minWidth),
      max: options.maxWidth && toPx(options.maxWidth),
      current: box.width,
      original: box.width,
    },
    heights: {
      min: toPx(options.minHeight),
      max: options.maxHeight && toPx(options.maxHeight),
      current: box.height,
      original: box.height,
    },
  }

  const listeners = [
    {
      node,
      event: 'pointerdown',
      handler: handlePointerDown,
    },
    {
      node,
      event: 'pointermove',
      handler: handlePointerMove,
    },
    {
      node,
      event: 'pointerup',
      handler: handlePointerUp,
    },
    {
      node,
      event: 'pointerleave',
      handler: handlePointerUp,
    },
  ]

  addListeners(listeners)

  function handlePointerDown(event) {
    const { x, y, pointerId } = event
    state.resizing = true
    state.prevX = x
    state.prevY = y
    state.pointerId = pointerId
    node.setPointerCapture(pointerId)
  }

  // TODO: Add a max-width to the resized element to ensure it don't allow overflow on mobile
  function handlePointerMove(event) {
    if (!state.resizing) return
    const { direction, canExceedOriginal } = options
    const { x, y } = event
    const deltaX = x - state.prevX
    const deltaY = y - state.prevY

    const {
      current: currentWidth,
      min: minWidth,
      max: maxWidth,
      original: originalWidth,
    } = state.widths

    const {
      current: currentHeight,
      min: minHeight,
      max: maxHeight,
      original: originalHeight,
    } = state.heights

    if (direction === 'horizontal') {
      const newWidth = currentWidth + deltaX
      switch (true) {
        case newWidth < minWidth:
          elementToResize.style.width = `${minWidth}px`
          break
        case maxWidth && newWidth > maxWidth:
          elementToResize.style.width = `${maxWidth}px`
          break
        case !canExceedOriginal && newWidth > originalWidth:
          elementToResize.style.width = `${originalWidth}px`
          break
        default:
          elementToResize.style.width = `${newWidth}px`
          break
      }
    }

    if (direction === 'vertical') {
      const newHeight = currentHeight + deltaY
      switch (true) {
        case newHeight < minHeight:
          elementToResize.style.height = `${minHeight}px`
          break
        case maxHeight && newHeight > maxHeight:
          elementToResize.style.height = `${maxHeight}px`
          break
        case !canExceedOriginal && newHeight > originalHeight:
          elementToResize.style.height = `${originalHeight}px`
          break
        default:
          elementToResize.style.height = `${newHeight}px`
      }
    }
  }

  function handlePointerUp(event) {
    const { width, height } = elementToResize.getBoundingClientRect()
    state.widths.current = width
    state.heights.current = height
    state.resizing = false
    if (state.pointerId) node.releasePointerCapture(state.pointerId)
  }

  return {
    destroy() {
      removeListeners(listeners)
    },
  }
}
